def transform(grid):
    """Expand the centered 2 into two diverging diagonals, then a 1 pattern."""
    n = len(grid[0])
    out = [[0] * n for _ in range(n)]
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    split = n // 2
    for r in range(n):
        if r <= split:
            for c in (center - r, center + r):
                if 0 <= c < n:
                    out[r][c] = 2
        for c in range((r - center) % 4, n, 4):
            out[r][c] = 1
    return out

